consultasKQLyVerificacion.consulta:
Connect-ExchangeOnline -ShowBanner:$false
ForEach ($p in Get-SupervisoryReviewPolicyV2 | Sort-Object Name) {
  $stats = Get-MailboxStatistics -Identity $p.ReviewMailbox -ErrorAction SilentlyContinue
  [PSCustomObject]@{ PolicyName = $p.Name; ReviewMailbox = $p.ReviewMailbox; ItemCount = $stats.ItemCount; TotalItemSize = $stats.TotalItemSize.ToString() }
}
